package io.github.jasper.monitoring.api.management.model;
public class ControlView { private final String id,systemScope,status; private final long version; protected ControlView(String id,String scope,String status,long version){if(id==null||id.trim().isEmpty()||scope==null||scope.trim().isEmpty()||version<1)throw new IllegalArgumentException("invalid control view");this.id=id;this.systemScope=scope;this.status=status;this.version=version;} public static ControlView of(String id,String scope,long version){return new ControlView(id,scope,"UNKNOWN",version);} public static ControlView of(String id,String scope,String status,long version){return new ControlView(id,scope,status,version);} public String getId(){return id;} public String getSystemScope(){return systemScope;} public String getStatus(){return status;} public long getVersion(){return version;} }
